// frontend/src/context/PermissionsContext.js
// Central role/permission logic for the frontend
// Mirrors the backend ROLE_PERMISSIONS matrix exactly

import React, { createContext, useContext } from 'react';
import { useAuth } from './AuthContext';

// Permission matrix — mirrors ProjectMember.ROLE_PERMISSIONS in models.py
const ROLE_PERMISSIONS = {
  super_admin:   { config:'full', planning:'full', journal:'full',  pointage:'full', budget:'full', qhse:'full', documents:'full', reports:'full', dashboard:'full', users:'full'  },
  chef_projet:   { config:'full', planning:'full', journal:'read',  pointage:'read', budget:'read', qhse:'read', documents:'full', reports:'full', dashboard:'full', users:'edit'  },
  maitre_oeuvre: { config:'read', planning:'read', journal:'none',  pointage:'none', budget:'none', qhse:'read', documents:'full', reports:'read', dashboard:'none', users:'none'  },
  conducteur:    { config:'read', planning:'read', journal:'full',  pointage:'full', budget:'none', qhse:'read', documents:'read', reports:'read', dashboard:'read', users:'none'  },
  chef_chantier: { config:'none', planning:'none', journal:'edit',  pointage:'full', budget:'none', qhse:'edit', documents:'none', reports:'none', dashboard:'none', users:'none'  },
  qhse:          { config:'none', planning:'none', journal:'read',  pointage:'none', budget:'none', qhse:'full', documents:'none', reports:'edit', dashboard:'none', users:'none'  },
  financier:     { config:'none', planning:'none', journal:'none',  pointage:'none', budget:'full', qhse:'none', documents:'none', reports:'edit', dashboard:'read', users:'none'  },
  magasinier:    { config:'none', planning:'none', journal:'none',  pointage:'none', budget:'read', qhse:'none', documents:'none', reports:'none', dashboard:'none', users:'none'  },
  sous_traitant: { config:'none', planning:'none', journal:'edit',  pointage:'full', budget:'none', qhse:'none', documents:'none', reports:'none', dashboard:'none', users:'none'  },
  client:        { config:'none', planning:'read', journal:'none',  pointage:'none', budget:'none', qhse:'none', documents:'none', reports:'read', dashboard:'read', users:'none'  },
};

export const ROLE_LABELS = {
  super_admin:   'Super Administrateur',
  chef_projet:   'Chef de Projet',
  maitre_oeuvre: "Maître d'Œuvre",
  conducteur:    'Conducteur de Travaux',
  chef_chantier: 'Chef de Chantier',
  qhse:          'Responsable QHSE',
  financier:     'Responsable Financier',
  magasinier:    'Magasinier',
  sous_traitant: 'Sous-traitant',
  client:        "Client / Maître d'Ouvrage",
};

export const ROLE_COLORS = {
  super_admin:   { bg: 'rgba(245,158,11,0.15)', color: '#F59E0B', border: 'rgba(245,158,11,0.3)' },
  chef_projet:   { bg: 'rgba(99,102,241,0.15)', color: '#818CF8', border: 'rgba(99,102,241,0.3)' },
  maitre_oeuvre: { bg: 'rgba(6,182,212,0.15)',  color: '#22D3EE', border: 'rgba(6,182,212,0.3)'  },
  conducteur:    { bg: 'rgba(16,185,129,0.15)', color: '#34D399', border: 'rgba(16,185,129,0.3)' },
  chef_chantier: { bg: 'rgba(249,115,22,0.15)', color: '#FB923C', border: 'rgba(249,115,22,0.3)' },
  qhse:          { bg: 'rgba(239,68,68,0.15)',  color: '#F87171', border: 'rgba(239,68,68,0.3)'  },
  financier:     { bg: 'rgba(34,197,94,0.15)',  color: '#4ADE80', border: 'rgba(34,197,94,0.3)'  },
  magasinier:    { bg: 'rgba(156,163,175,0.15)',color: '#9CA3AF', border: 'rgba(156,163,175,0.3)'},
  sous_traitant: { bg: 'rgba(168,85,247,0.15)', color: '#C084FC', border: 'rgba(168,85,247,0.3)' },
  client:        { bg: 'rgba(59,130,246,0.15)', color: '#60A5FA', border: 'rgba(59,130,246,0.3)' },
};

export const ROLE_ICONS = {
  super_admin:   '👑',
  chef_projet:   '🏗️',
  maitre_oeuvre: '📐',
  conducteur:    '🦺',
  chef_chantier: '⛏️',
  qhse:          '🛡️',
  financier:     '💰',
  magasinier:    '📦',
  sous_traitant: '🔧',
  client:        '🏛️',
};

// ── Permission helpers ────────────────────────────────────────────────────

export function getPermissions(role) {
  return ROLE_PERMISSIONS[role] || {};
}

export function can(role, module) {
  return getPermissions(role)[module] !== 'none' && getPermissions(role)[module] !== undefined;
}

export function canWrite(role, module) {
  const p = getPermissions(role)[module];
  return p === 'edit' || p === 'full';
}

export function canFull(role, module) {
  return getPermissions(role)[module] === 'full';
}

// ── Context ───────────────────────────────────────────────────────────────

const PermissionsContext = createContext(null);

export function PermissionsProvider({ children }) {
  const { user } = useAuth();
  const role = user?.platform_role || 'client';

  const value = {
    role,
    roleLabel:  ROLE_LABELS[role]  || role,
    roleColor:  ROLE_COLORS[role]  || ROLE_COLORS.client,
    roleIcon:   ROLE_ICONS[role]   || '👤',
    can:        (module) => can(role, module),
    canWrite:   (module) => canWrite(role, module),
    canFull:    (module) => canFull(role, module),
    isSuperAdmin: role === 'super_admin',
    isReadOnly:   role === 'client' || role === 'maitre_oeuvre',
    permissions: getPermissions(role),
  };

  return (
    <PermissionsContext.Provider value={value}>
      {children}
    </PermissionsContext.Provider>
  );
}

export function usePermissions() {
  return useContext(PermissionsContext);
}
